/**
 * Declaration is one server-compiled action/cost variant. Declarations, not
 * remaining currencies (ADR-0042): the client renders availability, identity,
 * target kind, and candidates verbatim and never derives game rules. Attack,
 * Move, End Turn, Activate and Death Save regenerate the selected offer before
 * execution.
 *
 * # One row per OFFER, not one row per verb
 *
 * Attack, Move and End Turn each compile exactly one, so for three verbs the
 * two readings coincided. VERB_ACTIVATE separates them: a level-1 barbarian
 * gets seven Activate declarations, and `slot` is what distinguishes Rage on
 * the bonus shape from Dodge on the action one. A consumer that indexes
 * declarations by verb, or that treats a second row for a verb as a producer
 * defect, is reading a coincidence as a contract.
 *
 * `id` remains the only thing execution echoes, and it is per-offer — so the
 * selector already identified the right row before there was more than one.
 *
 * @generated from message dnd5e.api.session.v1alpha1.Declaration
 */
export type Declaration = Message<"dnd5e.api.session.v1alpha1.Declaration"> & {
  /**
   * Which seam action this prices.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.Verb verb = 1;
   */
  verb: Verb;

  /**
   * Which economy shape this declaration would spend, or SLOT_NONE. Read off
   * the SAME SpendProfile the door would charge — never a table of what a
   * verb "usually" costs — so a class table changing what an action buys
   * changes this automatically.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.Slot slot = 2;
   */
  slot: Slot;

  /**
   * Whether every gate applicable to this verb currently passes. This is the
   * intentional source/JSON-name rename from `affordable = 3` to
   * `available = 3`: tag and wire shape stay fixed, but generated source names
   * and the JSON name change from `affordable` to `available`.
   *
   * @generated from field: bool available = 3;
   */
  available: boolean;

  /**
   * Provider-authored display/context for how much movement remains, in feet
   * (rpg-toolkit#1169). Present only for VERB_MOVE declarations; absent for
   * every VERB_ATTACK, VERB_END_TURN, VERB_ACTIVATE, and VERB_DEATH_SAVE
   * declaration.
   *
   * A NUMBER, NOT A PATH PRICE, because Move has no fixed cost until a path is
   * chosen. Clients may display this value verbatim but must not convert it to
   * cells, derive a path budget or cost from it, or use it to decide whether a
   * path will be accepted. The server prices the WHOLE requested path before
   * the first step and refuses it whole; `available` is likewise the server's
   * answer about whether any step is currently possible.
   *
   * `optional`, and this is the OTHER presence law at this seam — the
   * Outcome/Formed one (a message that is present or not), not the bool one
   * (a value that is never absent). Zero is a real answer here — nothing left
   * this turn — and must not collide with "this verb carries no such number at
   * all", which is what an Attack declaration says by leaving it unset. The
   * SDK carries it as a pointer with omitempty for exactly that reason, and
   * rpg-api's projection must keep absent absent: a nil that became 0 would
   * tell a client its attack has no feet left.
   *
   * @generated from field: optional int32 remaining = 5;
   */
  remaining?: number | undefined;

  /**
   * Present if and only if available is false. The server owns refusal
   * precedence. NO_TARGET_IN_REACH disables a compiled Attack without removing
   * its candidate rows.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.Shortfall why = 7;
   */
  why?: Shortfall | undefined;

  /**
   * Opaque deterministic selector for this current compiled offer. Non-empty
   * on every compiled Attack, turn-clock Move, End Turn, and Death Save
   * declaration; empty on an early per-verb blocker. The client echoes it and
   * never parses it.
   *
   * @generated from field: string id = 8;
   */
  id: string;

  /**
   * The sole public Attack identity. Present on every compiled Attack,
   * including compiled offers disabled by budget or target gates; absent for
   * Move, End Turn, Death Save, and early per-verb blockers.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.AttackRef attack = 9;
   */
  attack?: AttackRef | undefined;

  /**
   * Fixed for every compiled or blocked declaration: Attack -> MEMBER,
   * Move -> PATH, End Turn -> NONE, Death Save -> NONE, Activate -> MEMBER for
   * Help and NONE for the rest. UNSPECIFIED is a producer defect.
   *
   * Activate is the first verb whose kind varies by WHICH offer it is rather
   * than by which verb it is: Help prompts for an ally, and the other six
   * prompt for nothing. The rulebook draws a further line between "targets the
   * actor" (Dodge, Rage) and "targets nobody" (Dash) that this enum
   * deliberately does not: both are the same instruction to a client — do not
   * prompt — and whose sheet the effect lands on is the rulebook's business.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.TargetKind target_kind = 10;
   */
  targetKind: TargetKind;

  /**
   * Every member in the ruled candidate universe exactly once, including
   * unavailable targets and their server-authored reasons. NO_TARGET_IN_REACH
   * does not remove these rows. Empty for Move, End Turn, Death Save, and early
   * blockers.
   *
   * @generated from field: repeated dnd5e.api.session.v1alpha1.TargetCandidate candidates = 11;
   */
  candidates: TargetCandidate[];

  /**
   * The sole public activation identity. Present on every compiled Activate
   * declaration, including one disabled by a budget, charge or feature gate;
   * absent for Attack, Move, End Turn, Death Save, and early per-verb blockers.
   * The same presence law `attack` keeps, for the same reason.
   *
   * A SIBLING OF `attack` RATHER THAN A ONEOF WITH IT. A oneof would make it a
   * wire-level error for one declaration to carry both — and the monk's
   * bonus-action unarmed strike is exactly that: VERB_ATTACK on SLOT_BONUS,
   * gated on having taken the Attack action, which plausibly wants a weapon
   * identity AND the feature that granted the swing. That is a case we can
   * already name rather than a hypothetical, so the wire does not rule it out
   * in advance. If it turns out one declaration never needs both, a oneof can
   * be adopted later; a oneof adopted now cannot be undone without a break.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.AbilityRef ability = 12;
   */
  ability?: AbilityRef | undefined;

  /**
   * The provider-authored Death Save identity. Present only on a compiled
   * VERB_DEATH_SAVE declaration; absent for every other verb and blocker.
   *
   * Presence summary: an early per-verb blocker still emits its declaration
   * with available=false, why present, empty id, absent attack, empty
   * candidates, and the fixed target_kind. In particular, Afford emits the
   * Attack blocker even when Attack compilation cannot proceed. Compiled
   * offers use the field-presence rules above.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.DeathSaveRef death_save = 13;
   */
  deathSave?: DeathSaveRef | undefined;
};

